// Matriz de responsabilidades de los modelos de servicio de la nube. Corrige su defecto principal.
export const matriz = {
  filas: [
    { modelo: "SaaS", tarea: "Ejecutar y mantener el software", responsable: "PROVEEDOR" },
    { modelo: "SaaS", tarea: "Decidir cómo se usa el software", responsable: "CLIENTE" },
    { modelo: "PaaS", tarea: "Gestionar el hardware y los sistemas operativos subyacentes", responsable: "CLIENTE" },
    { modelo: "PaaS", tarea: "Desplegar y gestionar la aplicación", responsable: "CLIENTE" },
    { modelo: "IaaS", tarea: "Gestionar las redes, los equipos y el almacenamiento contratados", responsable: "CLIENTE" },
  ],
};

solution.code:
export const matriz = {
  filas: [
    { modelo: "SaaS", tarea: "Ejecutar y mantener el software", responsable: "PROVEEDOR" },
    { modelo: "SaaS", tarea: "Decidir cómo se usa el software", responsable: "CLIENTE" },
    { modelo: "PaaS", tarea: "Gestionar el hardware y los sistemas operativos subyacentes", responsable: "PROVEEDOR" },
    { modelo: "PaaS", tarea: "Desplegar y gestionar la aplicación", responsable: "CLIENTE" },
    { modelo: "IaaS", tarea: "Gestionar las redes, los equipos y el almacenamiento contratados", responsable: "CLIENTE" },
  ],
};

spec.code:
const fila = matriz.filas.find((f) => f.tarea === "Gestionar el hardware y los sistemas operativos subyacentes");
assert.ok(fila, "debe existir la fila del hardware subyacente");
assert.strictEqual(fila.modelo, "PaaS");
assert.strictEqual(fila.responsable, "PROVEEDOR");

for (const fila of matriz.filas) {
  assert.ok(["PROVEEDOR", "CLIENTE"].includes(fila.responsable), fila.tarea + " tiene un responsable no válido");
}

const esperado = {
  "Ejecutar y mantener el software": "PROVEEDOR",
  "Decidir cómo se usa el software": "CLIENTE",
  "Desplegar y gestionar la aplicación": "CLIENTE",
  "Gestionar las redes, los equipos y el almacenamiento contratados": "CLIENTE",
};
for (const [tarea, responsable] of Object.entries(esperado)) {
  const fila = matriz.filas.find((f) => f.tarea === tarea);
  assert.ok(fila, tarea + " debe seguir existiendo");
  assert.strictEqual(fila.responsable, responsable);
}

