// Clasifica el modelo de servicio según lo que gestiona el equipo. Corrige su defecto principal.
export interface Necesidad {
  gestionaInfraestructura: boolean;
  gestionaAplicacion: boolean;
}

export type Modelo = "IaaS" | "PaaS" | "SaaS";

export function modeloDeServicio(necesidad: Necesidad): Modelo {
  if (necesidad.gestionaAplicacion) {
    return "PaaS";
  }
  if (necesidad.gestionaInfraestructura) {
    return "IaaS";
  }
  return "SaaS";
}

solution.code:
export interface Necesidad {
  gestionaInfraestructura: boolean;
  gestionaAplicacion: boolean;
}

export type Modelo = "IaaS" | "PaaS" | "SaaS";

export function modeloDeServicio(necesidad: Necesidad): Modelo {
  if (necesidad.gestionaInfraestructura) {
    return "IaaS";
  }
  if (necesidad.gestionaAplicacion) {
    return "PaaS";
  }
  return "SaaS";
}

spec.code:
const a = modeloDeServicio({ gestionaInfraestructura: false, gestionaAplicacion: true });
const b = modeloDeServicio({ gestionaInfraestructura: true, gestionaAplicacion: true });
const c = modeloDeServicio({ gestionaInfraestructura: false, gestionaAplicacion: true });
assert.deepStrictEqual([a, b, c], ["PaaS", "IaaS", "PaaS"]);
